import{_ as n,c as a,a3 as e,o as p}from"./chunks/framework.DLXsHQLa.js";const o=JSON.parse('{"title":"ubuntu24.04增加老源的支持","description":"","frontmatter":{},"headers":[],"relativePath":"Linux系统/ubuntu桌面/ubuntu24.04增加老源的支持.md","filePath":"Linux系统/ubuntu桌面/ubuntu24.04增加老源的支持.md","lastUpdated":1720250676000}'),i={name:"Linux系统/ubuntu桌面/ubuntu24.04增加老源的支持.md"};function t(l,s,u,r,c,b){return p(),a("div",null,s[0]||(s[0]=[e(`<h1 id="ubuntu24-04增加老源的支持" tabindex="-1">ubuntu24.04增加老源的支持 <a class="header-anchor" href="#ubuntu24-04增加老源的支持" aria-label="Permalink to &quot;ubuntu24.04增加老源的支持&quot;">​</a></h1><p>比如网易邮件大师依赖老的ubuntu22.04的库libgconf-2-4，新版的ubuntu下不到就不兼容了。</p><p>ubuntu24的软件源歌格式已经变了:</p><p><code>vim /etc/apt/sources.list</code> 你会看到类似这样的内容：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span># Ubuntu sources have moved to /etc/apt/sources.list.d/ubuntu.sources</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>cat /etc/apt/sources.list.d/ubuntu.sources</code> ubuntu24.04的源是如下格式的：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Types: deb</span></span>
<span class="line"><span>URIs: http://archive.ubuntu.com/ubuntu</span></span>
<span class="line"><span>Suites: noble</span></span>
<span class="line"><span>Components: main restricted universe multiverse</span></span>
<span class="line"><span>Signed-By: /usr/share/keyrings/ubuntu-archive-keyring.gpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Types: deb</span></span>
<span class="line"><span>URIs: http://security.ubuntu.com/ubuntu/</span></span>
<span class="line"><span>Suites: noble-security</span></span>
<span class="line"><span>Components: universe restricted multiverse main</span></span>
<span class="line"><span>Signed-By: /usr/share/keyrings/ubuntu-archive-keyring.gpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>可以看到更加简洁了。</p><p>同时在linux上 xxx.d 一般是自动包含的，所以只需要把老的源文件复制到xxx.d下并修改一下(noble-&gt;jammy)即可。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> /etc/apt/sources.list.d/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> ubuntu.sources</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> ubuntu22.04.sources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFCB6B;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#C3E88D;"> ubuntu22.04.sources</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>我去除jammy-updates jammy-security，因为这个会影响其他软件比如snapd和系统。 输入以下内容：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Types: deb</span></span>
<span class="line"><span>URIs: http://archive.ubuntu.com/ubuntu/</span></span>
<span class="line"><span>Suites: jammy jammy-backports</span></span>
<span class="line"><span>Components: main restricted universe multiverse</span></span>
<span class="line"><span>Signed-By: /usr/share/keyrings/ubuntu-archive-keyring.gpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>修改完成之后直接安装网易邮件大师即可直接打开。</p>`,13)]))}const h=n(i,[["render",t]]);export{o as __pageData,h as default};
